<?php\n// modules/finance/PayrollReportGenerator.php - Generates all required reports (Step 15)\n\nnamespace Finance\\Services;\nuse PDO;\nuse Finance\\Core\\DbUtility; \n\n/**\n * Handles complex reporting queries for various financial outputs.\n */\nclass PayrollReportGenerator {\n    private DbUtility $dbUtil;\n    private PDO $pdo;\n\n    public function __construct(PDO $pdo, DbUtility $dbUtil) {\n        $this->pdo = $pdo;\n        $this->dbUtil = $dbUtil;\n    }\n\n    /**\n     * Generates a comprehensive Cost Report (Step 15.1).\n     * This report sums up all expenses posted to the GL via payroll run.\n     * @param int \$payrollRunId The run ID scope for the report.\n     * @return array|null Structured report data or null if no postings found.\n     */\n    public function generatePayrollCostReport(int $payrollRunId): ?array {\n        // Query payroll_finance_postings, joining to general ledger details table (if available).\n        $sql = \"SELECT \n                    SUM(CASE WHEN gl.account_id LIKE 'SALARY_EXPENSE%' THEN 1 ELSE 0 END) as salary_expense,\n                    SUM(CASE WHEN gl.account_id LIKE 'ALLOWANCE_EXPENSE%' THEN 1 ELSE 0 END) as allowance_expense,\n                    SUM(gl.debit) as total_payroll_cost\n                FROM general_ledger gl\n                JOIN payroll_finance_postings pfp ON gl.journal_entry_id = pfp.journal_entry_id\n                WHERE pfp.payroll_run_id = :pr_id AND gl.posting_date >= CURDATE() - INTERVAL 1 YEAR; // Example Date Filter\n        \";\n        // NOTE: Requires general_ledger and journal_entries tables to be fully implemented.\n        $stmt = $this->pdo->prepare($sql);\n        $stmt->execute([':pr_id' => $payrollRunId]);\n        return $stmt->fetch(PDO::FETCH_ASSOC) ?: null;\n    }\n\n    /**\n     * Generates a Department Payroll Report (Step 15.3).\n     * Requires linking GL account IDs back to specific departments, which is highly complex.\n     * @param string $departmentId Filter for department.\n     * @return array|null\n     */\n    public function generateDepartmentReport(string $departmentId): ?array {\n        // Logic Placeholder: Needs Department ID linkage in GL or employee tables.\n        return ['status' => 'INFO', 'message' => \"Department report logic requires mapping dept IDs to GL accounts.\"]; \n    }\n\n    /**\n     * Generates the Payroll Reconciliation Report (Step 15.8 & Step 12).\n     * This mostly involves retrieving data that was already compared in checkAndReconcile().\n     */\n    public function generateReconciliationReport(int $payrollRunId): ?array {\n        // In a real system, we would fetch the record from payroll_reconciliation table\n        $reportData = [ \n            'run_id' => $payrollRunId,\n            'status' => 'PENDING', // Should ideally reflect the status calculated by checkAndReconcile\n            'details' => \"Review totals against posted GL entries.\"\n        ];\n        return $reportData;\n    }\n    // Add methods for remaining reports (Salary Expense, Payable, etc.) as needed...\n}\n?>"